obs_rv_var = obs_sigma .^ 2



function get_loglikelihood(θ::Vector{Float64})
    rv_model = two_planets_rv_model(θ, obs_times)
    return -0.5 * sum(((obs_rv .- rv_model) .^ 2) ./ obs_rv_var .+ log.(2π .* obs_rv_var))
end



function get_gradient_loglikelihood(θ::Vector{Float64})
    rv_model = two_planets_rv_model(θ, obs_times)
    grad_rv_model = two_planets_rv_model_gradient(θ, obs_times)
    return ((obs_rv .- rv_model) ./ obs_rv_var)' * grad_rv_model
end



function get_metric_tensor(θ::Vector{Float64})
    grad_rv_model = two_planets_rv_model_gradient(θ, obs_times)
    return grad_rv_model' * (grad_rv_model ./ obs_rv_var)
end



