function Base.show(io::IO, hmb::HMB)
    println(io, "HMB index with $(hmb.K) DMUs")
    println(io, "  Input distance functions: $(typeof(hmb.In0))")
    println(io, "  Output distance functions: $(typeof(hmb.Out0))")
  end

  function Base.getindex(hmb::HMB, i::Int)
    if i < 1 || i > hmb.K
      throw(BoundsError(hmb, i))
    end
    return (hmb.In0[i], hmb.In1[i], hmb.Out0[i], hmb.Out1[i])
  end

  function Base.length(hmb::HMB)
    return hmb.K
  end

  function Base.iterate(hmb::HMB, state=1)
    if state > hmb.K
      return nothing
    end
    return (hmb[state], state+1)
  end

  function Base.eltype(::Type{HMB{S,T}}) where {S,T}
    return Tuple{typeof(S), typeof(T)}
  end

