function (src::HMB)(i::Int64)
    return (src.Out1(i)/src.Out0(i))/(src.In1(i)/src.In0(i))
end

function (src::HMB)(i::Int64,j::Int64)
    return (src.Out1(i)/src.Out0(j))/(src.In1(i)/src.In0(j))
end

function (src::HMB)()
    return [src(i) for i in 1:src.K]
end

# Outer constructor for HMB
function HMB{S,T}(X0::Array,Y0::Array,X1::Array,Y1::Array) where {S<:AbstractDataEnvelopment,T<:RS}
  return HMB{S,T}(X0,Y0,X1,Y1)
end

# Outer constructor without explicit type parameters
function HMB(X0::Array,Y0::Array,X1::Array,Y1::Array,tech::Type{S}=Convex,RS::Type{T}=VRS) where {S<:AbstractDataEnvelopment,T<:RS}
  return HMB{S,T}(X0,Y0,X1,Y1)
end

# Calculate the index for all DMUs
function evaluate(hmb::HMB)
  return [hmb[i] for i in 1:hmb.K]
end

