function psi_lower(B::Int, Qx = FlintQQ, a = 776)
  it = PrimesSet(2, B)
  g = bernstein(1, it, Qx, ceil, a)
  return _exp(g)
end

function psi_upper(B::Int, Qx = FlintQQ, a = 771)
  it = PrimesSet(2, B)
  g = bernstein(1, it, Qx, floor, a)
  return _exp(g)
end

function show_psi(B::Int, a = 776)
  l = psi_lower(B, FlintQQ, a)
  u = psi_upper(B, FlintQQ, 771)
  println("psi($B) is between $(sum(coeffs(l))) and $(sum(coeffs(u)))")
end

else
    return AlgAssRelOrdElem{S, T, U}(O, b, deepcopy(coordinates(a)))
  end
end

function (O::AlgAssRelOrd{S, T, U})(a::U, check::Bool = true) where {S, T, U}
  return O(basis_pmatrix(O, copy = false).matrix[1,1] * a, check)
end

