mutable struct Context
    device_type::CONTEXT_TYPE
    device_id::Int
end

Context(device_type::CONTEXT_TYPE=CPU) = Context(device_type, 0)
Context(device_type::Integer) = Context(CONTEXT_TYPE(device_type), 0)
Context(device_type::Integer, device_id::Integer) = Context(CONTEXT_TYPE(device_type), device_id)

device_type(ctx::Context) = ctx.device_type
device_id(ctx::Context) = ctx.device_id

function Base.show(io::IO, ctx::Context)
    print(io, "$(ctx.device_type):$(ctx.device_id)")
end

function Base.:(==)(a::Context, b::Context)
    return a.device_type == b.device_type && a.device_id == b.device_id
end

function Base.hash(ctx::Context, h::UInt)
    return hash(ctx.device_type, hash(ctx.device_id, h))
end

function gpu(device_id::Integer=0)
    return Context(GPU, device_id)
end

function cpu(device_id::Integer=0)
    return Context(CPU, device_id)
end

