    if isempty(vcInit)
      vc0 = norm(r) ^ 2 / n;
      vc1 = 1;
      wt = 1.0 ./ sqrt(vc1 * evalVfull + vc0);
    else
      vc0 = vcInit[1];
      # avoid sticky boundary
      if vc0 == 0
        vc0 = 1e-4;
      end
      vc1 = vcInit[2];
      if vc1 == 0
        vc1 = 1e-4;
      end
      wt = 1.0 ./ sqrt(vc1 * evalVfull + vc0);
      Xnew = scale(wt, Xrot);
      ynew = wt .* yrot;
      b = Xnew \ ynew;
    end

    # update residuals according supplied var. components
    r = y - BLAS.gemv('N', X, b);
    rnew = BLAS.gemv('T', UVfull, r);
    #deltaRes = norm(r) ^ 2 - norm(rnew) ^ 2;
    logl = loglConst + sum(log, wt) - 0.5 * sumabs2(rnew .* wt);

    nIters = 0;
