    denvec = Float64[];
    for iBlockAscent = 1:nBlockAscent

      nIters = iBlockAscent;

      # update variance components
      for iMM = 1:nMMmax
        denvec = 1.0 ./ (vc1 * evalVfull + vc0);
        numvec = rnew .* denvec;
        #vc0 = sqrt( (vc0 ^ 2 * sumabs2(numvec) + deltaRes) /
