        vc0 = vc0 * sqrt(sumabs2(numvec) / sumabs(denvec));
        vc1 = vc1 * sqrt( dot(numvec, numvec .* evalVfull) /
                           sumabs(evalVfull .* denvec) );
        #wt = 1.0 ./ sqrt(vc1 * evalVfull + vc0);
      end

      # update fixed effects and residuals
      #pb = pointer(b);
